S = 'التعرف على الألوان'
quiz('early', 'ألوان حولي', 'i_palette', ['a2', 'a3', 'a4'], 'التعلم المبكر', S, 'easy', 'أختار اللون الصحيح من الصور.', [
    PICI('أين اللون الأحمر؟', C['red'], [C['blue'], C['green']], 'هذا هو اللون الأحمر.', S, ['أحمر', 'أزرق', 'أخضر']),
    PICI('أين اللون الأزرق؟', C['blue'], [C['yellow'], C['red']], 'هذا هو اللون الأزرق.', S, ['أزرق', 'أصفر', 'أحمر']),
    PICI('أين اللون الأخضر؟', C['green'], [C['red'], C['yellow']], 'هذا هو اللون الأخضر.', S, ['أخضر', 'أحمر', 'أصفر']),
    MC('ما لون الموزة؟', 'أصفر', ['أحمر', 'أزرق'], 'الموزة صفراء.', S, img=ic('موزة'), oi=[C['yellow'], C['red'], C['blue']]),
    MC('ما لون العشب؟', 'أخضر', ['أصفر', 'أحمر'], 'العشب أخضر.', S, img=ic('عشب'), oi=[C['green'], C['yellow'], C['red']]),
    MC('ما لون الفراولة؟', 'أحمر', ['أزرق', 'أخضر'], 'الفراولة حمراء.', S, img=ic('فراولة'), oi=[C['red'], C['blue'], C['green']]),
], ('dict/?t=colors', 'مراجعة الألوان في المعجم المصور'), tags=['pictures'], minutes=3)
S = 'مطابقة الأشكال'
