    PICI('أين المربع؟', 'rd_square_green', ['rd_circle_green', 'rd_triangle_green'], 'هذا مربع.', S, ['مربع', 'دائرة', 'مثلث']),
    PICI('أين المثلث؟', 'rd_triangle_yellow', ['rd_circle_yellow', 'rd_square_yellow'], 'هذا مثلث.', S, ['مثلث', 'دائرة', 'مربع']),
    MATCH('صل كل اسم بالشكل المناسب', [('دائرة', None, 'rd_circle_blue'), ('مربع', None, 'rd_square_blue'), ('مثلث', None, 'rd_triangle_blue')], 'أحسنت، طابقت الأشكال.', S),
    OBS('اختر كل المربعات', [('rd_square_red',), ('rd_circle_red',), ('rd_square_blue',), ('rd_triangle_green',), ('rd_square_green',)], [0, 2, 4], 'المربعات هي ذات الأضلاع الأربعة المتساوية.', S),
