S = 'التعرف على الحروف'
def lt(L, ans, wr):
    for a in [ans] + wr: pass
    return PIC(ans, wr, S, q='أين صورة تبدأ بحرف %s؟' % L)
quiz('early', 'الحروف الأولى', 'u_letters', E4, 'التعلم المبكر', S, 'easy', 'أجد الصورة التي تبدأ بالحرف.', [
    lt('الباء', 'بطة', ['قطة', 'أسد']), lt('القاف', 'قطة', ['بطة', 'جمل']), lt('الجيم', 'جمل', ['فيل', 'قرد']), lt('الفاء', 'فيل', ['جمل', 'كلب']),
    MC('ما الحرف الأول في كلمة كلب؟', 'ك', ['ل', 'ب'], 'كلب تبدأ بحرف الكاف.', S, img=ic('كلب')),
    MC('ما الحرف الأول في كلمة أسد؟', 'أ', ['س', 'د'], 'أسد تبدأ بحرف الألف.', S, img=ic('أسد')),
], ('language/', 'دروس الحروف في قسم اللغات'), tags=['letters'], minutes=3)
